	void interruptibleAcquisitionReportsAnInterruptWhileTheLockIsHeld() throws Exception {
		SailModelCleanup.Lock lock = new SailModelCleanup.Lock();
		AtomicReference<Throwable> outcome = new AtomicReference<>();
		lock.lock();
		try {
			Thread waiter = new Thread(() -> {
				try {
					lock.lockInterruptibly();
					lock.unlock();
					outcome.set(new AssertionError("acquired a held lock"));
				} catch (InterruptedException interrupted) {
					outcome.set(interrupted);
				}
			});
			waiter.start();
			while (!lock.hasQueuedThread(waiter)) {
				Thread.onSpinWait();
			}
			waiter.interrupt();
			waiter.join(TimeUnit.SECONDS.toMillis(10));
		} finally {
			lock.unlock();
		}
		assertInstanceOf(InterruptedException.class, outcome.get());
		assertFalse(lock.isLocked());

		Thread.currentThread().interrupt();
		try {
			assertThrows(InterruptedException.class, lock::lockInterruptibly);
		} finally {
			Thread.interrupted();
		}
		assertFalse(lock.isLocked());
	}

